function calculateEconomicImpact(diagnosis, cropType) {
  const baseLoss = {
    olive: 5e3,
    citrus: 8e3,
    tomato: 12e3,
    wheat: 3e3,
    artichoke: 7e3
  };
  const severityMultiplier = {
    low: 0.1,
    medium: 0.3,
    high: 0.6
  };
  const cropLoss = baseLoss[cropType] || 5e3;
  const severityFactor = severityMultiplier[diagnosis.severity] || 0.3;
  const potentialLoss = Math.round(cropLoss * severityFactor);
  const treatmentCost = Math.round(potentialLoss * 0.15);
  const recoveryTime = {
    low: "1-2 \u0623\u0633\u0627\u0628\u064A\u0639",
    medium: "3-4 \u0623\u0633\u0627\u0628\u064A\u0639",
    high: "6-8 \u0623\u0633\u0627\u0628\u064A\u0639"
  };
  return {
    potentialLoss,
    treatmentCost,
    recoveryTime: recoveryTime[diagnosis.severity] || "3-4 \u0623\u0633\u0627\u0628\u064A\u0639"
  };
}
