// server/services/farmService.ts
init_supabase();
var FarmService = class {
  // Farm operations
  static async getAllFarms() {
    const { data, error } = await supabase.from("farms").select("*").order("created_at", { ascending: false });
    if (error)
      throw error;
    return data;
  }
  static async getFarmById(farmId) {
    const { data, error } = await supabase.from("farms").select("*").eq("id", farmId).single();
    if (error)
      throw error;
    return data;
  }
  static async createFarm(farm) {
    const { data, error } = await supabase.from("farms").insert(farm).select().single();
    if (error)
      throw error;
    return data;
  }
  static async updateFarm(farmId, updates) {
    const { data, error } = await supabase.from("farms").update({ ...updates, updated_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", farmId).select().single();
    if (error)
      throw error;
    return data;
  }
  static async deleteFarm(farmId) {
    const { error } = await supabase.from("farms").delete().eq("id", farmId);
    if (error)
      throw error;
  }
  // Field operations
  static async getFieldsByFarmId(farmId) {
    const { data, error } = await supabase.from("fields").select("*").eq("farm_id", farmId).order("created_at", { ascending: false });
    if (error)
      throw error;
    return data;
  }
  static async getFieldById(fieldId) {
    const { data, error } = await supabase.from("fields").select("*").eq("id", fieldId).single();
    if (error)
      throw error;
    return data;
  }
  static async createField(field) {
    const { data, error } = await supabase.from("fields").insert(field).select().single();
    if (error)
      throw error;
    return data;
  }
  static async updateField(fieldId, updates) {
    const { data, error } = await supabase.from("fields").update({ ...updates, updated_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", fieldId).select().single();
    if (error)
      throw error;
    return data;
  }
  static async deleteField(fieldId) {
    const { error } = await supabase.from("fields").delete().eq("id", fieldId);
    if (error)
      throw error;
  }
  // Soil data operations
  static async getSoilDataByFieldId(fieldId, limit = 10) {
    const { data, error } = await supabase.from("soil_data").select("*").eq("field_id", fieldId).order("measured_at", { ascending: false }).limit(limit);
    if (error)
      throw error;
    return data;
  }
  static async createSoilData(soilData) {
    const { data, error } = await supabase.from("soil_data").insert(soilData).select().single();
    if (error)
      throw error;
    return data;
  }
  static async getLatestSoilData(fieldId) {
    const { data, error } = await supabase.from("soil_data").select("*").eq("field_id", fieldId).order("measured_at", { ascending: false }).limit(1).single();
    if (error)
      throw error;
    return data;
  }
};

