var getNotifications = async (req, res) => {
  try {
    const {
      category,
      priority,
      status,
      limit = 50,
      offset = 0,
      search,
      userId
    } = req.query;
    let filteredNotifications = mockNotifications;
    if (category && category !== "all") {
      filteredNotifications = filteredNotifications.filter((n) => n.category === category);
    }
    if (priority && priority !== "all") {
      filteredNotifications = filteredNotifications.filter((n) => n.priority === priority);
    }
    if (status) {
      switch (status) {
        case "unread":
          filteredNotifications = filteredNotifications.filter((n) => !n.isRead);
          break;
        case "read":
          filteredNotifications = filteredNotifications.filter((n) => n.isRead);
          break;
        case "starred":
          filteredNotifications = filteredNotifications.filter((n) => n.isStarred);
          break;
        case "archived":
          filteredNotifications = filteredNotifications.filter((n) => n.isArchived);
          break;
        case "active":
          filteredNotifications = filteredNotifications.filter((n) => !n.isArchived);
          break;
      }
    }
    if (search) {
      const searchLower = search.toString().toLowerCase();
      filteredNotifications = filteredNotifications.filter(
        (n) => n.title.toLowerCase().includes(searchLower) || n.titleArabic.includes(searchLower) || n.message.toLowerCase().includes(searchLower) || n.messageArabic.includes(searchLower)
      );
    }
    if (userId) {
      filteredNotifications = filteredNotifications.filter(
        (n) => n.targetUsers.includes(userId.toString())
      );
    }
    filteredNotifications.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    const startIndex = Number(offset);
    const endIndex = startIndex + Number(limit);
    const paginatedNotifications = filteredNotifications.slice(startIndex, endIndex);
    res.json({
      success: true,
      data: paginatedNotifications,
      pagination: {
        total: filteredNotifications.length,
        limit: Number(limit),
        offset: Number(offset),
        hasMore: endIndex < filteredNotifications.length
      }
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: "Failed to fetch notifications"
    });
  }
};
