import multer2 from "file:///root/app/code/node_modules/multer/index.js";
var AI_SERVICES = {
  SOIL_ANALYSIS: process.env.SOIL_ANALYSIS_URL || "http://localhost:8001",
  CROP_RECOMMENDATION: process.env.CROP_RECOMMENDATION_URL || "http://localhost:8002",
  IMAGE_DIAGNOSIS: process.env.IMAGE_DIAGNOSIS_URL || "http://localhost:8003",
  MARKET_FORECAST: process.env.MARKET_FORECAST_URL || "http://localhost:8004",
  SMART_ASSISTANT: process.env.SMART_ASSISTANT_URL || "http://localhost:8005",
  SMART_MARKETPLACE: process.env.SMART_MARKETPLACE_URL || "http://localhost:8006"
};
var upload2 = multer2({
  storage: multer2.memoryStorage(),
  limits: {
    fileSize: 10 * 1024 * 1024
    // 10MB limit
  },
  fileFilter: (req, file, cb) => {
    if (file.mimetype.startsWith("image/")) {
      cb(null, true);
    } else {
      cb(new Error("Only image files are allowed"), false);
    }
  }
});
var handleAIServiceError = (error, serviceName, res) => {
  console.error(`Error calling ${serviceName}:`, error.message);
  if (error.response) {
    res.status(error.response.status).json({
      error: `${serviceName} service error`,
      message: error.response.data || error.message,
      status: error.response.status
    });
  } else if (error.request) {
    res.status(503).json({
      error: `${serviceName} service unavailable`,
      message: "Service is not responding",
      status: 503
    });
  } else {
    res.status(500).json({
      error: "Internal server error",
      message: error.message,
      status: 500
    });
  }
};
var callAIService = async (serviceUrl, endpoint, method = "POST", data, headers) => {
  const url = `${serviceUrl}${endpoint}`;
  const config = {
    method,
    url,
    timeout: 3e4,
    // 30 seconds timeout
    headers: {
      "Content-Type": "application/json",
      ...headers
    },
    ...data && { data }
  };
  return axios(config);
};
var analyzeSoilData = async (req, res) => {
  try {
    const response = await callAIService(
      AI_SERVICES.SOIL_ANALYSIS,
      "/analyze-soil",
      "POST",
      req.body
    );
    res.json(response.data);
  } catch (error) {
    handleAIServiceError(error, "Soil Analysis", res);
  }
};
