var userRewards = [];
var userActivities = [];
function calculateLevel(totalXP) {
  for (let i = LEVEL_PROGRESSION.length - 1; i >= 0; i--) {
    if (totalXP >= LEVEL_PROGRESSION[i]) {
      return i;
    }
  }
  return 0;
}
function getXPForNextLevel(currentLevel) {
  if (currentLevel >= LEVEL_PROGRESSION.length - 1) {
    return 0;
  }
  return LEVEL_PROGRESSION[currentLevel + 1];
}
function generateUserId() {
  return Math.random().toString(36).substr(2, 9);
}
function initializeUserRewards(userId) {
  const newUser = {
    id: generateUserId(),
    userId,
    currentXP: 0,
    currentLevel: 0,
    totalXP: 0,
    badges: [],
    achievements: [],
    lastActivityDate: (/* @__PURE__ */ new Date()).toISOString(),
    streak: 1
  };
  userRewards.push(newUser);
  return newUser;
}
function getUserRewards(userId) {
  let user = userRewards.find((u) => u.userId === userId);
  if (!user) {
    user = initializeUserRewards(userId);
  }
  return user;
}
function checkBadgeEligibility(userId, userReward) {
  const newBadges = [];
  const userActivitiesCount = userActivities.filter((a) => a.userId === userId);
  AVAILABLE_BADGES.forEach((badgeTemplate) => {
    if (userReward.badges.some((b) => b.name === badgeTemplate.name)) {
      return;
    }
    let eligible = false;
    switch (badgeTemplate.category) {
      case "soil":
        eligible = userActivitiesCount.filter((a) => a.action === "soil_analysis").length >= 10;
        break;
      case "disease":
        eligible = userActivitiesCount.filter((a) => a.action === "disease_detection").length >= 25;
        break;
      case "ai":
        eligible = userActivitiesCount.filter((a) => a.action === "crop_recommendation").length >= 50;
        break;
      case "engagement":
        eligible = userReward.streak >= 30;
        break;
      case "special":
        eligible = false;
        break;
    }
    if (eligible) {
      const newBadge = {
        ...badgeTemplate,
        id: generateUserId(),
        earnedAt: (/* @__PURE__ */ new Date()).toISOString()
      };
      newBadges.push(newBadge);
    }
  });
  return newBadges;
}
var getUserProfile = async (req, res) => {
  try {
    const userId = req.query.userId || "demo-user";
    const userReward = getUserRewards(userId);
    const lastActivity = new Date(userReward.lastActivityDate);
    const today = /* @__PURE__ */ new Date();
    const diffDays = Math.floor(
      (today.getTime() - lastActivity.getTime()) / (1e3 * 3600 * 24)
    );
    if (diffDays === 1) {
      userReward.streak += 1;
      userReward.lastActivityDate = today.toISOString();
    } else if (diffDays > 1) {
      userReward.streak = 1;
      userReward.lastActivityDate = today.toISOString();
    }
    const nextLevelXP = getXPForNextLevel(userReward.currentLevel);
    const currentLevelXP = userReward.currentLevel > 0 ? LEVEL_PROGRESSION[userReward.currentLevel] : 0;
    const progressToNext = nextLevelXP > 0 ? (userReward.totalXP - currentLevelXP) / (nextLevelXP - currentLevelXP) * 100 : 100;
    res.json({
      success: true,
      data: {
        ...userReward,
        nextLevelXP,
        currentLevelXP,
        progressToNext: Math.min(progressToNext, 100),
        xpToNextLevel: Math.max(nextLevelXP - userReward.totalXP, 0)
      }
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: "Failed to get user profile",
      message: error instanceof Error ? error.message : "Unknown error"
    });
  }
};
var awardXP = async (req, res) => {
  try {
    const { userId = "demo-user", action, metadata } = req.body;
    const xpEvent = XP_REWARDS[action];
    if (!xpEvent) {
      return res.status(400).json({
        success: false,
        error: "Invalid action",
        message: `Action '${action}' not found`
      });
    }
    let userReward = getUserRewards(userId);
    const oldLevel = userReward.currentLevel;
    userReward.totalXP += xpEvent.xp;
    userReward.currentXP = userReward.totalXP;
    userReward.currentLevel = calculateLevel(userReward.totalXP);
    userReward.lastActivityDate = (/* @__PURE__ */ new Date()).toISOString();
    userActivities.push({
      userId,
      action,
      xp: xpEvent.xp,
      timestamp: (/* @__PURE__ */ new Date()).toISOString(),
      metadata
    });
    const leveledUp = userReward.currentLevel > oldLevel;
    const newBadges = checkBadgeEligibility(userId, userReward);
    userReward.badges.push(...newBadges);
    res.json({
      success: true,
      data: {
        xpAwarded: xpEvent.xp,
        totalXP: userReward.totalXP,
        currentLevel: userReward.currentLevel,
        leveledUp,
        levelsGained: userReward.currentLevel - oldLevel,
        newBadges,
        event: xpEvent
      }
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: "Failed to award XP",
      message: error instanceof Error ? error.message : "Unknown error"
    });
  }
};
