function calculateInvestorMetrics(portfolio) {
  const totalInvested = portfolio.reduce(
    (sum, item) => sum + item.investmentAmount,
    0
  );
  const totalReturns = portfolio.reduce(
    (sum, item) => sum + (item.currentValue - item.investmentAmount),
    0
  );
  const activeInvestments = portfolio.filter(
    (item) => item.status === "active"
  ).length;
  const completedInvestments = portfolio.filter(
    (item) => item.status === "completed"
  ).length;
  const averageReturn = portfolio.length > 0 ? portfolio.reduce((sum, item) => sum + item.returns, 0) / portfolio.length : 0;
  const portfolioValue = portfolio.reduce(
    (sum, item) => sum + item.currentValue,
    0
  );
  const riskCounts = { low: 0, medium: 0, high: 0 };
  riskCounts.low = Math.floor(portfolio.length * 0.4);
  riskCounts.medium = Math.floor(portfolio.length * 0.4);
  riskCounts.high = portfolio.length - riskCounts.low - riskCounts.medium;
  const cropDiversification = {};
  portfolio.forEach((item) => {
    cropDiversification[item.cropType] = (cropDiversification[item.cropType] || 0) + item.investmentAmount;
  });
  const regionDiversification = {};
  portfolio.forEach((item) => {
    regionDiversification[item.region] = (regionDiversification[item.region] || 0) + item.investmentAmount;
  });
  return {
    totalInvested: Math.round(totalInvested),
    totalReturns: Math.round(totalReturns),
    activeInvestments,
    completedInvestments,
    averageReturn: Math.round(averageReturn * 10) / 10,
    portfolioValue: Math.round(portfolioValue),
    monthlyGrowth: 2 + Math.random() * 8,
    // Mock monthly growth
    riskDiversification: riskCounts,
    cropDiversification,
    regionDiversification
  };
}
var getInvestmentOpportunities = async (req, res) => {
  try {
    const {
      cropType,
      region,
      riskLevel,
      minReturn,
      maxInvestment,
      sortBy = "expectedReturn",
      order = "desc",
      limit = 10,
      offset = 0
    } = req.query;
    let opportunities = generateInvestmentOpportunities();
    if (cropType) {
      opportunities = opportunities.filter(
        (opp) => opp.cropType.toLowerCase().includes(cropType.toLowerCase())
      );
    }
    if (region) {
      opportunities = opportunities.filter(
        (opp) => opp.region.toLowerCase().includes(region.toLowerCase())
      );
    }
    if (riskLevel) {
      opportunities = opportunities.filter(
        (opp) => opp.riskLevel === riskLevel
      );
    }
    if (minReturn) {
      opportunities = opportunities.filter(
        (opp) => opp.expectedReturn >= Number(minReturn)
      );
    }
    if (maxInvestment) {
      opportunities = opportunities.filter(
        (opp) => opp.investmentRequired <= Number(maxInvestment)
      );
    }
    opportunities.sort((a, b) => {
      const aValue = a[sortBy];
      const bValue = b[sortBy];
      return order === "desc" ? bValue - aValue : aValue - bValue;
    });
    const paginatedOpportunities = opportunities.slice(
      Number(offset),
      Number(offset) + Number(limit)
    );
    res.json({
      success: true,
      data: {
        opportunities: paginatedOpportunities,
        total: opportunities.length,
        filters: {
          cropType,
          region,
          riskLevel,
          minReturn,
          maxInvestment
        },
        pagination: {
          limit: Number(limit),
          offset: Number(offset),
          total: opportunities.length
        }
      }
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: "Failed to get investment opportunities",
      message: error instanceof Error ? error.message : "Unknown error"
    });
  }
};
