var getPostReplies = async (req, res) => {
  try {
    const { postId } = req.params;
    const { limit = 20, offset = 0 } = req.query;
    let postReplies = forumReplies.filter((reply) => reply.postId === postId).sort(
      (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
    ).slice(Number(offset), Number(offset) + Number(limit));
    const repliesWithAuthors = postReplies.map((reply) => ({
      ...reply,
      author: getUserById(reply.authorId)
    }));
    res.json({
      success: true,
      data: repliesWithAuthors
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: "Failed to get post replies",
      message: error instanceof Error ? error.message : "Unknown error"
    });
  }
};
var getOnlineExperts = async (req, res) => {
  try {
    const { specialization, limit = 10 } = req.query;
    let experts = users.filter(
      (user) => user.userType === "expert" && user.verified && user.online
    );
    if (specialization) {
      experts = experts.filter(
        (expert) => expert.specializations.some(
          (spec) => spec.toLowerCase().includes(specialization.toLowerCase())
        ) || expert.specializationsArabic.some(
          (spec) => spec.includes(specialization)
        )
      );
    }
    experts.sort((a, b) => b.rating - a.rating);
    experts = experts.slice(0, Number(limit));
    res.json({
      success: true,
      data: experts
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: "Failed to get online experts",
      message: error instanceof Error ? error.message : "Unknown error"
    });
  }
};
var getCollaborationStats = async (req, res) => {
  try {
    const totalUsers = users.length;
    const onlineUsers = users.filter((u) => u.online).length;
    const totalExperts = users.filter((u) => u.userType === "expert").length;
    const verifiedExperts = users.filter(
      (u) => u.userType === "expert" && u.verified
    ).length;
    const totalConsultations = consultations.length;
    const activeConsultations = consultations.filter(
      (c) => c.status === "in_progress" || c.status === "assigned"
    ).length;
    const completedConsultations = consultations.filter(
      (c) => c.status === "completed"
    ).length;
    const totalForumPosts = forumPosts.length;
    const totalChatRooms = chatRooms.filter((r) => r.active).length;
    const totalMessages = messages.length;
    const averageExpertRating = verifiedExperts > 0 ? users.filter((u) => u.userType === "expert" && u.verified).reduce((sum, expert) => sum + expert.rating, 0) / verifiedExperts : 0;
    res.json({
      success: true,
      data: {
        users: {
          total: totalUsers,
          online: onlineUsers,
          experts: totalExperts,
          verifiedExperts
        },
        consultations: {
          total: totalConsultations,
          active: activeConsultations,
          completed: completedConsultations,
          completionRate: totalConsultations > 0 ? completedConsultations / totalConsultations * 100 : 0
        },
        forum: {
          totalPosts: totalForumPosts,
          featuredPosts: forumPosts.filter((p) => p.featured).length,
          totalReplies: forumReplies.length
        },
        chat: {
          totalRooms: totalChatRooms,
          totalMessages,
          averageMessagesPerRoom: totalChatRooms > 0 ? totalMessages / totalChatRooms : 0
        },
        quality: {
          averageExpertRating: Math.round(averageExpertRating * 100) / 100,
          totalReviews: users.reduce((sum, user) => sum + user.reviewCount, 0)
        },
        lastUpdated: (/* @__PURE__ */ new Date()).toISOString()
      }
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: "Failed to get collaboration stats",
      message: error instanceof Error ? error.message : "Unknown error"
    });
  }
};

